namespace sv_9c49251ebbaf417483290f69976d2216.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds theme state for a single circuit (user session).
/// Components subscribe to <see cref="OnChange"/> to re-render when the theme updates.
/// </summary>
public sealed class ThemeService
{
    private Theme _theme = Theme.System;
    private string _accentColor = "#0d6efd"; // Bootstrap primary blue

    public Theme CurrentTheme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyStateChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyStateChanged();
        }
    }

    /// <summary>
    /// Raised whenever <see cref="CurrentTheme"/> or <see cref="AccentColor"/> changes.
    /// </summary>
    public event Action? OnChange;

    /// <summary>
    /// Apply multiple changes in one batch so OnChange fires only once.
    /// </summary>
    public void SetPreferences(Theme theme, string accentColor)
    {
        bool changed = _theme != theme || _accentColor != accentColor;
        _theme = theme;
        _accentColor = accentColor;
        if (changed) NotifyStateChanged();
    }

    private void NotifyStateChanged() => OnChange?.Invoke();
}

