@page "/settings"
@rendermode InteractiveServer
@using sv_9c49251ebbaf417483290f69976d2216.Services
@inject ThemeService Theme
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Appearance</h5>

        <div class="mb-3">
            <label class="form-label">Theme</label>
            <select class="form-select"
                    value="@_selectedTheme"
                    @onchange="OnThemeInput">
                @foreach (var t in Enum.GetValues<Theme>())
                {
                    <option value="@t">@t</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <div class="d-flex align-items-center gap-2">
                <input type="color"
                       class="form-control form-control-color"
                       value="@_selectedAccent"
                       @onchange="OnAccentInput" />
                <span class="text-muted">@_selectedAccent</span>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="Save"
                style="background-color: @Theme.AccentColor; border-color: @Theme.AccentColor;">
            Save Preferences
        </button>

        @if (_saved)
        {
            <span class="text-success ms-2">✓ Saved</span>
        }
    </div>
</div>

<div class="mt-4 p-3 border rounded" style="border-color: @Theme.AccentColor !important;">
    <strong>Live preview:</strong>
    Theme = <em>@Theme.CurrentTheme</em>, Accent =
    <span style="color: @Theme.AccentColor;">@Theme.AccentColor</span>
</div>

@code {
    private Theme _selectedTheme;
    private string _selectedAccent = string.Empty;
    private bool _saved;

    protected override void OnInitialized()
    {
        _selectedTheme = Theme.CurrentTheme;
        _selectedAccent = Theme.AccentColor;
        Theme.OnChange += OnThemeServiceChanged;
    }

    public void Dispose() => Theme.OnChange -= OnThemeServiceChanged;

    private void OnThemeServiceChanged()
    {
        _selectedTheme = Theme.CurrentTheme;
        _selectedAccent = Theme.AccentColor;
        InvokeAsync(StateHasChanged);
    }

    private void OnThemeInput(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var t))
            _selectedTheme = t;
    }

    private void OnAccentInput(ChangeEventArgs e)
    {
        _selectedAccent = e.Value?.ToString() ?? _selectedAccent;
    }

    private void Save()
    {
        Theme.SetPreferences(_selectedTheme, _selectedAccent);
        _saved = true;
    }
}

